~~~python
"""P5 by TheOne; mirror 0146f8fda31c06c390c4911747eec099954fd591.
One request per row/repeat; no retries. --stop-usd is a before-next-call threshold,
not a hard final-bill cap. Unknown cost stops; output is created, never overwritten.
Row indexes are zero-based; run numbers are one-based. Photos stay out of output.
"""
import argparse
from decimal import Decimal
import json
from pathlib import Path


def _cost(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return None
    try:
        d = Decimal(str(value))
        return d if d.is_finite() and d >= 0 else None
    except (ValueError, ArithmeticError):
        return None


def run(rows, repeats, question, stop, cfg, headers, out, read, data_url, image_part, send):
    count, total = 0, Decimal(0)
    for i, row in enumerate(rows):
        if total >= stop:
            return count, 0
        ref = read(row["ref"])
        cand = ref if row["kind"] == "same" and "cand" not in row else read(row["cand"])
        content = [image_part(data_url(ref)), image_part(data_url(cand)),
                   {"type": "text", "text": question}]
        for n in range(1, repeats + 1):
            if total >= stop:
                return count, 0
            request = {"model": cfg["model"], "messages": [{"role": "user", "content": content}],
                       "max_tokens": 600, "provider": {"data_collection": "deny"},
                       "usage": {"include": True}}
            record = dict(kind=row["kind"], row=i, run=n, answer=None,
                          tokens_in=None, tokens_out=None, cost=None, status="unavailable")
            cost = None
            try:
                response = send(request, headers, cfg["timeout"])
                if response["status"] == 200:
                    body = response["body"]
                    usage = body.get("usage", {})
                    cost = _cost(usage.get("cost"))
                    if cost is not None:
                        record["cost"] = usage["cost"]
                    for key, field in (("prompt_tokens", "tokens_in"), ("completion_tokens", "tokens_out")):
                        v = usage.get(key)
                        record[field] = v if type(v) is int and v >= 0 else None
                    choice = body["choices"][0]
                    answer = choice["message"]["content"]
                    if isinstance(answer, str):
                        record["answer"] = answer
                        record["status"] = "ok" if cost is not None else "unknown_cost"
                    finish = choice.get("finish_reason")
                    record["finish_reason"] = finish if finish in ("stop", "length", "content_filter") else None
            except Exception:
                pass  # Never print response data, exception text, paths or headers.
            out.write(json.dumps(record, ensure_ascii=True, allow_nan=False) + "\n")
            out.flush()
            count += 1
            if cost is None or record["status"] != "ok":
                return count, 1
            total += cost
    return count, 0


class _Parser(argparse.ArgumentParser):
    def error(self, message):
